def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    transitions = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * size)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    from collections import deque

    failure = [0] * len(transitions)
    queue = deque()

    for c in range(size):
        state = transitions[0][c]
        if state == -1:
            transitions[0][c] = 0
        else:
            queue.append(state)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for c in range(size):
            nxt = transitions[state][c]
            if nxt == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[nxt] = transitions[failure[state]][c]
                queue.append(nxt)

    safe = [state for state in range(len(transitions)) if not terminal[state]]
    compact = {state: i for i, state in enumerate(safe)}
    count = len(safe)

    matrix = [[0] * count for _ in range(count)]
    for state in safe:
        row = matrix[compact[state]]
        for nxt in transitions[state]:
            if not terminal[nxt]:
                row[compact[nxt]] += 1

    vector = [0] * count
    vector[compact[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] += value * weight
            vector = [value % MOD for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] += value * weight
                squared[i] = [value % MOD for value in squared[i]]
            matrix = squared

    return sum(vector) % MOD
